public/schemas/bitrouter.config.schema.j.content:
{
  "$defs": {
    "AccountStrategy": {
      "description": "How a multi-account provider's per-account targets are ordered.",
      "oneOf": [
        {
          "const": "failover",
          "description": "Accounts in declared order — the first is primary; routing drops\nto the next on a retryable failure (5xx / 429 / timeout) or a\npayment / credit-exhaustion error. The default.",
          "type": "string"
        },
        {
          "const": "balance",
          "description": "Accounts ordered with a process-random rotation so the primary\n(and therefore the load) spreads evenly across accounts. The\nremaining accounts still act as failover targets for that\nrequest.",
          "type": "string"
        }
      ]
    },
    "AcpAgentConfig": {
      "description": "One configured upstream ACP agent, as written in `bitrouter.yaml` under\n`agents:`.\n\nThe same `name` is what every `bro acp` subcommand addresses an\nagent by, and what [`AcpAgentConfig::validate`] constrains.",
      "properties": {
        "name": {
          "description": "Agent id. Non-empty; no `/`.",
          "type": "string"
        },
        "transport": {
          "$ref": "#/$defs/AcpTransport",
          "description": "Wire transport."
        }
      },
      "required": [
        "name",
        "transport"
      ],
      "type": "object"
    },
    "AcpRecordingConfig": {
      "description": "Local ACP conversation content recording, independent of routing evidence.",
      "properties": {
        "enabled": {
          "default": false,
          "description": "Store observable session messages and tool results until explicitly deleted.\nNo content is recorded or sent to an evaluator by default.",
          "type": "boolean"
        }
      },
      "type": "object"
    },
    "AcpTransport": {
      "description": "How to dial one upstream ACP agent.\n\nv1.0 ships stdio only — the spec lists stdio as the primary transport for\nagent processes spawned by an IDE / CLI client.",
      "oneOf": [
        {
          "description": "Stdio transport: launch `command` with `args` and exchange JSON-RPC\nover the child's stdin/stdout.",
          "properties": {
            "args": {
              "default": [],
              "description": "Arguments to pass to the child.",
              "items": {
                "type": "string"
              },
              "type": "array"
            },
            "command": {
              "description": "The program to spawn (resolved via `$PATH`).",
              "type": "string"
            },
            "env": {
              "additionalProperties": {
                "type": "string"
              },
              "default": {},
              "description": "Extra environment variables for the child. Inherited env is kept.",
              "type": "object"
            },
            "type": {
              "const": "stdio",
              "type": "string"
            }
          },
          "required": [
            "type",
            "command"
          ],
          "type": "object"
        }
      ]
    },
    "AgentApiConfig": {
      "additionalProperties": false,
      "description": "Privileged HTTP access to the BRO task service. The app validates a\nloopback listener, nonempty token environment variable, and workspace\nallowlist before binding; `server.skip_auth` never grants this authority.",
      "properties": {
        "enabled": {
          "default": false,
          "description": "Whether to bind the task HTTP listener.",
          "type": "boolean"
        },
        "listen": {
          "default": "127.0.0.1:4359",
          "description": "Loopback host and port, distinct from inference and control.",
          "type": "string"
        },
        "token_env": {
          "default": "",
          "description": "Environment variable containing the dedicated task bearer token.",
          "type": "string"
        },
        "workspaces": {
          "default": [],
          "description": "Exact server-owned workspace paths admitted for task submission.",
          "items": {
            "type": "string"
          },
          "type": "array"
        }
      },
      "type": "object"
    },
    "ApiProtocol": {
      "description": "Wire protocol. Known values: `chat_completions`, `messages`, `responses`, `decisions`; any other string names an externally-registered (outbound-only) custom protocol.",
      "examples": [
        "chat_completions",
        "messages",
        "responses",
        "decisions"
      ],
      "type": "string"
    },
    "Capability": {
      "description": "An optional inference feature a request may require and a provider may\nadvertise. Capabilities are API-agnostic: the same capability maps to a\ndifferent wire parameter in each protocol (structured outputs is Chat\nCompletions' `response_format`, Messages' `output_config.format`, Generate\nContent's `responseSchema`, Responses' `text.format`). The serde\nrepresentation (e.g. `structured_outputs`) is the stable token used to match\na request's needs against a provider's advertised capabilities.\n\nA capability-aware `RoutingTable`\ncan read the set a request requires ([`Prompt::required_capabilities`]) and\nrestrict the chain to providers advertising all of them.",
      "oneOf": [
        {
          "const": "structured_outputs",
          "description": "JSON-Schema-constrained output — [`ResponseFormat::JsonSchema`].",
          "type": "string"
        },
        {
          "const": "tools",
          "description": "Tool / function calling — the request supplies a non-empty tool list.",
          "type": "string"
        },
        {
          "const": "reasoning",
          "description": "Extended reasoning / thinking — the request sets a reasoning-effort hint.",
          "type": "string"
        },
        {
          "const": "web_search",
          "description": "Provider-side web search / browsing.",
          "type": "string"
        },
        {
          "const": "logprobs",
          "description": "Token log-probabilities in the response.",
          "type": "string"
        },
        {
          "const": "image_input",
          "description": "Image input (vision) — a message carries an `image/*` file part.",
          "type": "string"
        },
        {
          "const": "audio_input",
          "description": "Audio input — a message carries an `audio/*` file part.",
          "type": "string"
        },
        {
          "const": "video_input",
          "description": "Video input — a message carries a `video/*` file part.",
          "type": "string"
        },
        {
          "const": "file_input",
          "description": "Document / file input — a message carries a non-image/audio/video file\npart (e.g. `application/pdf`).",
          "type": "string"
        },
        {
          "const": "image_output",
          "description": "Image output (generation) — the request asks for an `image` output\nmodality.",
          "type": "string"
        },
        {
          "const": "audio_output",
          "description": "Audio output (speech) — the request asks for an `audio` output modality.",
          "type": "string"
        }
      ]
    },
    "ChatCompletionsCompatibility": {
      "description": "Chat Completions request-shape compatibility settings.",
      "properties": {
        "google_extensions": {
          "default": false,
          "description": "Enable the demonstrated Google Chat extensions for this selected model.\nSigned tool history additionally requires a credential-bound replay proof.",
          "type": "boolean"
        },
        "supports_store": {
          "default": null,
          "description": "Whether this target accepts the optional `store` request field. `None`\npreserves the OpenAI-compatible default (supported).",
          "type": [
            "boolean",
            "null"
          ]
        },
        "supports_stream_options": {
          "default": null,
          "description": "Whether this target accepts `stream_options`. `None` preserves the\nOpenAI-compatible default (supported, with `include_usage` injected).\nSetting this to `false` also disables the router's usage-chunk request,\nso it is appropriate only when the target rejects the entire object.",
          "type": [
            "boolean",
            "null"
          ]
        },
        "token_limit_field": {
          "anyOf": [
            {
              "$ref": "#/$defs/ChatTokenLimitField"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Token-limit field required by this upstream model."
        }
      },
      "type": "object"
    },
    "ChatConfig": {
      "description": "`bro chat`'s own configuration.",
      "properties": {
        "agent": {
          "default": null,
          "description": "Default ACP harness for bare `bitrouter` (catalog id or configured agent).",
          "type": [
            "string",
            "null"
          ]
