          "default": [],
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "sort": {
          "anyOf": [
            {
              "$ref": "#/$defs/SortOrder"
            },
            {
              "type": "null"
            }
          ],
          "default": null
        }
      },
      "type": "object"
    },
    "RouterSelection": {
      "description": "Model selection performed by a named router.",
      "oneOf": [
        {
          "additionalProperties": false,
          "description": "Resolve one existing model selector.",
          "properties": {
            "kind": {
              "const": "model",
              "type": "string"
            },
            "model": {
              "description": "Existing physical or virtual model selector.",
              "type": "string"
            },
            "routing": {
              "$ref": "#/$defs/RouterRoutingConfig",
              "default": {
                "ignore": [],
                "only": [],
                "require_tags": [],
                "sort": null
              },
              "description": "Provider preferences applied by the existing cascade resolver."
            }
          },
          "required": [
            "kind",
            "model"
          ],
          "type": "object"
        },
        {
          "additionalProperties": false,
          "description": "Let one existing policy choose the effective model.",
          "properties": {
            "base_model": {
              "description": "Exact base-model input retained by the current policy runtime.",
              "type": "string"
            },
            "kind": {
              "const": "policy",
              "type": "string"
            },
            "policy": {
              "description": "Policy name in `policy-lock.yaml`.",
              "type": "string"
            },
            "routing": {
              "$ref": "#/$defs/RouterRoutingConfig",
              "default": {
                "ignore": [],
                "only": [],
                "require_tags": [],
                "sort": null
              },
              "description": "Provider preferences applied after the policy selects a model."
            }
          },
          "required": [
            "kind",
            "policy",
            "base_model"
          ],
          "type": "object"
        }
      ]
    },
    "RoutingConfig": {
      "description": "Routing knobs shared by presets and variants.",
      "properties": {
        "ignore": {
          "default": [],
          "description": "Drop these providers from the chain.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "only": {
          "default": [],
          "description": "Restrict the chain to exactly these providers.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "require_tags": {
          "default": [],
          "description": "Require providers carrying all these tags.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "sort": {
          "anyOf": [
            {
              "$ref": "#/$defs/SortOrder"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Cascade-chain ordering."
        }
      },
      "type": "object"
    },
    "ServerConfig": {
      "description": "HTTP server settings.",
      "properties": {
        "control_socket": {
          "default": "./bitrouter.sock",
          "description": "Unix control socket path.",
          "type": "string"
        },
        "listen": {
          "default": "0.0.0.0:4356",
          "description": "`host:port` to listen on.",
          "type": "string"
        },
        "log_level": {
          "default": "info",
          "description": "Log filter for the daemon, in `tracing-subscriber` `EnvFilter` syntax —\na bare level (`debug`) or a per-target list (`info,bitrouter=debug`).\n\n`RUST_LOG` overrides this when set, following the Rust convention. The\nfilter is resolved once at startup, so changing it needs a restart —\n`bro reload` will not pick it up. Applies to `bro serve`\n(and therefore `start`); other subcommands install their subscriber\nbefore any config is read and honour `RUST_LOG` only.",
          "type": "string"
        },
        "require_known_pricing": {
          "default": false,
          "description": "Deny dispatch when any routed tariff cannot guarantee complete known-price\ncoverage. Decisions caching remains unverified and fails this admission.",
          "type": "boolean"
        },
        "skip_auth": {
          "default": false,
          "description": "SDK-level flag: when `true`, credential-less requests are admitted with\na synthesised local caller. Code default is **`false`** — only the\nconfig file produced by `bro init` writes `true`.",
          "type": "boolean"
        }
      },
      "type": "object"
    },
    "ServerToolsConfig": {
      "description": "The OSS `server_tools` config section. Names the MCP servers whose tools\nBitRouter attaches to LLM requests and executes inside the loop, with an\noptional override of the loop's iteration cap. An empty `mcp_servers`\nleaves the pipeline strictly single-shot.",
      "properties": {
        "advisor": {
          "default": false,
          "description": "Enable the `advisor` server tool (consult a stronger model mid-task).\nAdvertised per-request only when the caller declares `bitrouter:advisor`.",
          "type": "boolean"
        },
        "fusion": {
          "anyOf": [
            {
              "$ref": "#/$defs/FusionSettings"
            },
            {
              "type": "null"
            }
          ],
          "description": "Multi-model deliberation (Fusion). When set, the `bitrouter:fusion`\nserver tool and the `bitrouter/fusion` model alias are enabled."
        },
        "max_iterations": {
          "default": null,
          "description": "Optional override of the loop's maximum tool-execution rounds.",
          "format": "uint32",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        },
        "mcp_servers": {
          "default": [],
          "description": "MCP server names (keys of `mcp_servers`) whose tools are injected into\nLLM requests and executed by the loop.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "subagent": {
          "default": false,
          "description": "Enable the `subagent` server tool (delegate a task to a worker model).\nAdvertised per-request only when the caller declares `bitrouter:subagent`.",
          "type": "boolean"
        },
        "web_fetch": {
          "anyOf": [
            {
              "$ref": "#/$defs/WebFetchSettings"
            },
            {
              "type": "null"
            }
          ],
          "description": "Built-in `web_fetch` server tool (BYOK). When set, the\n`bitrouter:web_fetch` tool is enabled, served by the configured fetch\nbackends. Advertised per-request only when the caller declares it."
        },
        "web_search": {
          "anyOf": [
            {
              "$ref": "#/$defs/WebSearchSettings"
            },
            {
              "type": "null"
            }
          ],
          "description": "Built-in `web_search` server tool (BYOK). When set, the\n`bitrouter:web_search` tool is enabled, served by the configured search\nbackends. Advertised per-request only when the caller declares it."
        }
      },
      "type": "object"
    },
    "SortOrder": {
      "description": "How a cascade chain should be ordered.",
      "oneOf": [
        {
          "const": "alphabetical",
          "description": "Sort by provider name, ascending. The Phase-1 default; later replaced by\na recommender (cost / latency / throughput scoring).",
          "type": "string"
        },
        {
          "const": "latency",
          "description": "Sort by lowest latency first.",
          "type": "string"
        },
        {
          "const": "cost",
          "description": "Sort by lowest cost first.",
          "type": "string"
        }
      ]
    },
    "TimeoutConfig": {
      "description": "Upstream HTTP timeout knobs, in seconds. Every field is optional; an unset\nfield inherits the level above — a provider override inherits the resolved\nglobal value, and an unset global inherits the built-in default\n([`HttpTimeouts::default`]). `total_secs` is opt-in at every level: unset ⇒\nno overall wall-clock cap (the right default for long agentic streams).\n\nUsed both as the top-level `upstream.timeouts` block and as the per-provider\n`providers.<id>.timeouts` override; timeouts are **not** inherited via a\nprovider's `derives:` chain.",
      "properties": {
        "connect_secs": {
          "default": null,
          "description": "TCP connect timeout, seconds.",
          "format": "uint64",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        },
        "pool_idle_secs": {
          "default": null,
          "description": "Idle pooled-connection eviction, seconds.",
          "format": "uint64",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        },
        "read_secs": {
          "default": null,
          "description": "Idle (per-read) timeout, seconds — fires when the upstream sends no\nbytes for this long, including mid-stream. The effective stream-idle\nguard.",
          "format": "uint64",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        },
        "tcp_keepalive_secs": {
          "default": null,
          "description": "TCP keepalive probe interval, seconds.",
          "format": "uint64",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        },
        "total_secs": {
          "default": null,
          "description": "Overall wall-clock cap for the entire request/stream, seconds. Opt-in:\nunset ⇒ no cap. Setting it bounds total stream duration, so keep it\ngenerous for reasoning / agentic providers.",
          "format": "uint64",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        }
      },
      "type": "object"
    },
    "TrajectoryConfig": {
      "description": "Durable trajectory progress-control settings.",
      "properties": {
        "enabled": {
          "default": false,
          "description": "Explicit opt-in for durable trajectory routing and settlement.",
          "type": "boolean"
        },
        "outbox_batch_size": {
          "default": 100,
          "description": "Maximum durable outbox rows attempted in one publication batch.",
          "format": "uint",
          "minimum": 0,
          "type": "integer"
        },
        "retention_days": {
          "default": 30,
          "description": "Age boundary used by startup retention, in whole days.",
          "format": "uint32",
          "minimum": 0,
          "type": "integer"
        }
      },
      "type": "object"
    },
    "UpstreamConfig": {
      "description": "Outbound / upstream HTTP settings — the client BitRouter uses to call\nproviders. Distinct from [`ServerConfig`], which is the inbound listen\nsocket. Currently just [`timeouts`](Self::timeouts); grouped under\n`upstream:` so future outbound knobs have a home.",
      "properties": {
        "fallback_backoff_ms": {
          "default": [],
          "description": "Optional delay schedule before advancing through a retryable fallback\nchain, in milliseconds. The first value applies before the second\ncandidate, the second before the third, and the last value repeats when\nthe chain is longer than the schedule. Empty (the default) preserves\nimmediate fallback.",
          "items": {
            "format": "uint64",
            "minimum": 0,
            "type": "integer"
          },
          "type": "array"
        },
        "timeouts": {
          "$ref": "#/$defs/TimeoutConfig",
          "description": "Global upstream timeout defaults. A provider may override any field\nunder `providers.<id>.timeouts:`."
        }
      },
      "type": "object"
    },
    "VariantConfig": {
      "description": "A `:variant` definition — a routing modifier only.",
      "properties": {
        "routing": {
          "$ref": "#/$defs/RoutingConfig",
          "default": {
            "ignore": [],
            "only": [],
            "require_tags": [],
            "sort": null
          },
          "description": "Routing knobs fed into the cascade."
        }
      },
      "type": "object"
    },
    "VirtualEndpoint": {
      "description": "One endpoint of a virtual model.",
      "properties": {
        "provider": {
          "description": "The provider id this endpoint routes to.",
          "type": "string"
        },
        "service_id": {
          "description": "The service / model id at that provider.",
          "type": "string"
        }
      },
      "required": [
        "provider",
        "service_id"
      ],
      "type": "object"
    },
    "VirtualModel": {
      "description": "An explicit virtual-model definition (Strategy 2).",
      "properties": {
        "endpoints": {
          "description": "The endpoints this virtual model maps to. Their meaning depends on\n[`strategy`](Self::strategy): under `priority` they are an *ordered*\npreference list; under `cascade` the order is a starting point that\nthe cascade ordering then re-sorts.",
          "items": {
            "$ref": "#/$defs/VirtualEndpoint"
          },
          "type": "array"
        },
        "pricing": {
          "anyOf": [
            {
              "$ref": "#/$defs/PricingConfig"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional pricing for the virtual model."
        },
        "strategy": {
          "$ref": "#/$defs/VirtualModelStrategy",
          "description": "How this virtual model's [`endpoints`](Self::endpoints) are ordered\ninto the fallback chain. See [`VirtualModelStrategy`]. Defaults to\n[`Priority`](VirtualModelStrategy::Priority)."
        }
      },
      "required": [
        "endpoints"
      ],
      "type": "object"
    },
    "VirtualModelStrategy": {
      "description": "How a [`VirtualModel`]'s endpoints are ordered into its fallback chain\n(Strategy 2). Mirrors the typed-enum + serde pattern of\n[`AccountStrategy`].\n\nBoth strategies build a chain that `execute_with_fallback` walks: a\nretryable failure (5xx / 408 / 429 / timeout / credit-exhaustion) always\nadvances to the next endpoint — that failover-on-error behaviour is a\nproperty of *any* chain and is shared by both. They differ only in the\n**order** the endpoints take in that chain.",
      "oneOf": [
        {
          "const": "priority",
          "description": "Endpoints are tried in **declared YAML order** — the first is the\npreferred endpoint, the rest are failover targets reached only when a\npreceding one fails with a retryable error. Routing preferences\n(`sort` / `only` / `ignore`) do **not** reorder or filter the chain:\nthe operator's declared priority is authoritative. This is the\ndefault and matches the historical (pre-typed-`strategy`) behaviour.",
          "type": "string"
        },
        {
          "const": "cascade",
          "description": "Endpoints are treated as an unordered candidate set and **re-ordered by\nthe request's [`SortOrder`]** (the same cascade ordering Strategy-3\nauto-cascade applies to providers), and filtered by `only` / `ignore` /\n`require_tags`.\nUse this when the endpoints are interchangeable and you want\ncost/latency-aware (or, today, alphabetical) selection rather than a\nfixed priority order. `Latency` / `Cost` have no metrics source yet, so\nthey currently fall back to alphabetical-by-provider — the same honest\nlimitation Strategy-3 documents.",
          "type": "string"
        }
      ]
    },
    "WebFetchBackendConfig": {
      "description": "One configured extraction backend. The `kind` tag selects the engine; the\nBYOK key resolves from `api_key` (supports `${VAR}` substitution) or, when\nomitted, the engine's conventional environment variable.",
      "oneOf": [
        {
          "description": "exa.ai `/contents` — key `api_key` or `EXA_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `EXA_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "exa",
              "type": "string"
            }
          },
          "required": [
            "kind"
          ],
          "type": "object"
        },
        {
          "description": "firecrawl.dev `/v2/scrape` — key `api_key` or `FIRECRAWL_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `FIRECRAWL_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "firecrawl",
              "type": "string"
            }
          },
          "required": [
            "kind"
          ],
          "type": "object"
        },
        {
          "description": "tavily.com `/extract` — key `api_key` or `TAVILY_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `TAVILY_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "tavily",
              "type": "string"
            }
          },
          "required": [
            "kind"
          ],
          "type": "object"
        }
      ]
    },
    "WebFetchSettings": {
      "description": "The `server_tools.web_fetch` section. Its presence enables the\n`bitrouter:web_fetch` server tool (advertised only when a request declares\nit). An empty `backends` list leaves the tool effectively off.",
      "properties": {
        "backends": {
          "description": "Extraction backends in preference/failover order; the first that resolves\na key is the default.",
          "items": {
            "$ref": "#/$defs/WebFetchBackendConfig"
          },
          "type": "array"
        },
        "max_content_tokens": {
          "default": null,
          "description": "Default cap on returned content per fetch, in tokens (caller may lower\nit). Defaults to [`DEFAULT_MAX_CONTENT_TOKENS`].",
          "format": "uint32",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        }
      },
      "type": "object"
    },
    "WebSearchBackendConfig": {
      "description": "One configured search backend. The `kind` tag selects the engine; the BYOK\nkey resolves from `api_key` (supports `${VAR}` substitution) or, when\nomitted, the engine's conventional environment variable.",
      "oneOf": [
        {
          "description": "parallel.ai — key `api_key` or `PARALLEL_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `PARALLEL_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "parallel",
              "type": "string"
            }
          },
          "required": [
            "kind"
          ],
          "type": "object"
        },
        {
          "description": "exa.ai — key `api_key` or `EXA_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `EXA_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "exa",
              "type": "string"
            }
          },
          "required": [
            "kind"
          ],
          "type": "object"
        },
        {
          "description": "firecrawl.dev — key `api_key` or `FIRECRAWL_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `FIRECRAWL_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "firecrawl",
              "type": "string"
            }
          },
          "required": [
            "kind"
          ],
          "type": "object"
        },
        {
          "description": "tavily.com — key `api_key` or `TAVILY_API_KEY`.",
          "properties": {
            "api_base": {
              "default": null,
              "description": "Endpoint override (else the engine default).",
              "type": [
                "string",
                "null"
              ]
            },
            "api_key": {
              "default": null,
              "description": "Explicit API key (else `TAVILY_API_KEY`).",
              "type": [
                "string",
                "null"
              ]
            },
            "kind": {
              "const": "tavily",
              "type": "string"
            }
          },
          "required": [
