  "$id": "https://bitrouter.dev/schema/v1.0.0-alpha.33/config.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "description": "The top-level configuration.",
  "properties": {
    "acp_recording": {
      "$ref": "#/$defs/AcpRecordingConfig",
      "default": {
        "enabled": false
      },
      "description": "Opt-in local storage of observable ACP conversation content."
    },
    "agent_api": {
      "$ref": "#/$defs/AgentApiConfig",
      "description": "Opt-in privileged BRO coding task API, separate from inference and control."
    },
    "agents": {
      "additionalProperties": {
        "$ref": "#/$defs/AcpAgentConfig"
      },
      "default": {},
      "description": "Upstream ACP agents, keyed by agent id. Surfaced by the\n`bro agents` CLI (list / check / install). Empty by default.",
      "type": "object"
    },
    "chat": {
      "$ref": "#/$defs/ChatConfig",
      "description": "The interactive session's own configuration."
    },
    "checkers": {
      "additionalProperties": {
        "$ref": "#/$defs/CheckerConfig"
      },
      "default": {},
      "description": "Compiled request-check extensions, keyed by the ids referenced from named routers.",
      "type": "object"
    },
    "continuation": {
      "$ref": "#/$defs/ContinuationConfig",
      "default": {
        "prune_batch_size": 1000,
        "retention_days": 30
      },
      "description": "Durable provider continuation mapping lifecycle."
    },
    "control": {
      "$ref": "#/$defs/ControlConfig",
      "description": "Opt-in, read-only operator control API settings."
    },
    "database": {
      "$ref": "#/$defs/DatabaseConfig",
      "description": "Database connection settings."
    },
    "decision_model": {
      "anyOf": [
        {
          "$ref": "#/$defs/DecisionModelConfig"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "Typed decision backend for native context routing. Absent means the\nconservative compiler runs without remote semantic judgments."
    },
    "eval": {
      "$ref": "#/$defs/EvalConfig",
      "default": {
        "authorities": {}
      },
      "description": "Generic evaluation exchange authorities and admission scopes."
    },
    "inherit_defaults": {
      "default": true,
      "description": "Whether providers inherit workspace defaults.",
      "type": "boolean"
    },
    "mcp": {
      "$ref": "#/$defs/McpConfig",
      "description": "Top-level MCP gateway settings (aggregation, caching). All fields\ndefault — `mcp:` is optional in `bitrouter.yaml`."
    },
    "mcp_servers": {
      "additionalProperties": {
        "$ref": "#/$defs/McpServerConfig"
      },
      "default": {},
      "description": "Upstream MCP servers, keyed by server id. The id is what appears in\n`POST /mcp/{id}` and what the `mcp` pipeline's routing table looks up.\nEmpty by default — when empty, the binary does not mount the MCP route.",
      "type": "object"
    },
    "models": {
      "additionalProperties": {
        "$ref": "#/$defs/VirtualModel"
      },
      "description": "Explicit virtual-model definitions (Strategy 2.2). Optional —\nwhen absent, bare model names fall through to Strategy 3 auto-cascade.",
      "type": "object"
    },
    "plugins": {
      "additionalProperties": true,
      "default": {},
      "description": "Plugin config, keyed by plugin / bundle id.",
      "type": "object"
    },
    "policy": {
      "$ref": "#/$defs/PolicyConfig",
      "default": {
        "mode": "frozen",
        "path": null
      },
      "description": "Adaptive model-policy settings. A file-backed config resolves the\noptional path relative to its own directory; when omitted the app looks\nfor `policy-lock.yaml` next to `bitrouter.yaml`. The SDK only carries\nthis declaration -- loading and evolving policy locks belongs to the\nBitRouter app layer."
    },
    "presets": {
      "additionalProperties": {
        "$ref": "#/$defs/PresetConfig"
      },
      "description": "`@preset` definitions.",
      "type": "object"
    },
    "providers": {
      "additionalProperties": {
        "$ref": "#/$defs/ProviderConfig"
      },
      "description": "Upstream providers, keyed by provider id.",
      "type": "object"
    },
    "registry": {
      "$ref": "#/$defs/RegistryConfig",
      "description": "Public registry integration: whether to fetch + merge the registry's\nBYOK providers, where to fetch it from, and the provider-class priority\nladder used to order the auto-cascade."
    },
    "routers": {
      "additionalProperties": {
        "$ref": "#/$defs/RouterConfig"
      },
      "default": {},
      "description": "Named request routers, addressed as `bitrouter/<id>`.",
      "type": "object"
    },
    "server": {
      "$ref": "#/$defs/ServerConfig",
      "description": "HTTP server settings."
    },
    "server_tools": {
      "$ref": "#/$defs/ServerToolsConfig",
      "description": "Server-side tool loop: MCP server ids whose tools BitRouter injects into\nLLM requests and executes itself. Empty by default — the pipeline stays\nsingle-shot."
    },
    "trajectory": {
      "$ref": "#/$defs/TrajectoryConfig",
      "default": {
        "enabled": false,
        "outbox_batch_size": 100,
        "retention_days": 30
      },
      "description": "Durable trajectory progress-control and local operations settings."
    },
    "upstream": {
      "$ref": "#/$defs/UpstreamConfig",
      "description": "Outbound / upstream HTTP settings (the client that calls providers)."
    },
    "variants": {
      "additionalProperties": {
        "$ref": "#/$defs/VariantConfig"
      },
      "description": "`:variant` definitions.",
      "type": "object"
    }
  },
  "title": "BitRouter config",
  "type": "object"
}
